-- Catalog of neural networks for staged Replicate / provider integration.
-- Safe to re-run: upserts by slug.

CREATE EXTENSION IF NOT EXISTS pgcrypto;

CREATE TABLE IF NOT EXISTS neural_networks (
  id                 UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  name               TEXT NOT NULL,
  slug               TEXT NOT NULL UNIQUE,
  category           TEXT NOT NULL CHECK (category IN ('llm', 'image', 'video', 'audio', 'editor')),
  api_available      BOOLEAN NOT NULL DEFAULT FALSE,
  api_provider       TEXT NOT NULL DEFAULT 'pending',
  input_modalities   TEXT[] NOT NULL DEFAULT '{}',
  output_modalities  TEXT[] NOT NULL DEFAULT '{}',
  status             TEXT NOT NULL DEFAULT 'catalog'
                       CHECK (status IN ('catalog', 'integrating', 'live', 'blocked')),
  replicate_model    TEXT NULL,
  notes              TEXT NULL,
  created_at         TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at         TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS neural_networks_category_idx ON neural_networks (category);
CREATE INDEX IF NOT EXISTS neural_networks_status_idx ON neural_networks (status);

ON CONFLICT (slug) DO UPDATE SET
  name = EXCLUDED.name,
  category = EXCLUDED.category,
  api_available = EXCLUDED.api_available,
  api_provider = EXCLUDED.api_provider,
  input_modalities = EXCLUDED.input_modalities,
  output_modalities = EXCLUDED.output_modalities,
  status = EXCLUDED.status,
  replicate_model = EXCLUDED.replicate_model,
  notes = EXCLUDED.notes,
  updated_at = now();
